namespace CarScanner.Services.Localization;

// Batch 11: technical-inspection checklist (part 2), market part names, module scan field names. Order: tr, de, pl, es, pt, fr, it.
internal static partial class LanguagePacks
{
    private static IEnumerable<(string En, string[] T)> ExtraRows21() => new (string En, string[] T)[]
    {
        R("Horn not working", "Korna çalışmıyor", "Hupe funktioniert nicht", "Klakson nie działa", "El claxon no funciona", "A buzina não funciona", "L’avertisseur ne fonctionne pas", "Il clacson non funziona"),
        R("Identification", "Kimlik", "Identifikation", "Identyfikacja", "Identificación", "Identificação", "Identification", "Identificazione"),
        R("If the car has none, choose \"OK\".", "Araçta yoksa “Tamam”ı seç.", "Hat das Fahrzeug keine, wähle „OK“.", "Jeśli auto go nie ma, wybierz „OK”.", "Si el coche no tiene, elige «OK».", "Se o carro não tiver, escolha «OK».", "Si la voiture n’en a pas, choisissez « OK ».", "Se l’auto non ce l’ha, scegli «OK»."),
        R("If unsure, ask a mechanic or look under the car. Without a catalyst the CO limit usually cannot be met.", "Emin değilsen bir tamirciye sor veya aracın altına bak. Katalizör olmadan CO sınırı genellikle karşılanamaz.", "Wenn du unsicher bist, frage einen Mechaniker oder sieh unter das Fahrzeug. Ohne Katalysator lässt sich der CO-Grenzwert meist nicht einhalten.", "Jeśli nie jesteś pewien, zapytaj mechanika lub zajrzyj pod auto. Bez katalizatora zwykle nie da się spełnić limitu CO.", "Si no estás seguro, pregunta a un mecánico o mira bajo el coche. Sin catalizador normalmente no se cumple el límite de CO.", "Se tiver dúvidas, pergunte a um mecânico ou veja debaixo do carro. Sem catalisador, o limite de CO normalmente não é cumprido.", "En cas de doute, demandez à un mécanicien ou regardez sous la voiture. Sans catalyseur, la limite de CO ne peut généralement pas être respectée.", "Se non sei sicuro, chiedi a un meccanico o guarda sotto l’auto. Senza catalizzatore di solito il limite di CO non si rispetta."),
        R("Ignition on, foot on the brake, select reverse and check a reflection or a video.", "Kontak açık, ayak frende, geri vitesi seç ve bir yansımaya veya videoya bak.", "Zündung an, Fuß auf der Bremse, Rückwärtsgang einlegen und eine Spiegelung oder ein Video prüfen.", "Zapłon włączony, noga na hamulcu, wybierz bieg wsteczny i sprawdź odbicie lub nagranie.", "Contacto dado, pie en el freno, selecciona marcha atrás y comprueba un reflejo o un vídeo.", "Ignição ligada, pé no travão, engate a marcha-atrás e verifique um reflexo ou um vídeo.", "Contact mis, pied sur le frein, passez la marche arrière et vérifiez un reflet ou une vidéo.", "Quadro acceso, piede sul freno, inserisci la retromarcia e controlla un riflesso o un video."),
        R("Inspect and replace the worn parts.", "Aşınmış parçaları incele ve değiştir.", "Prüfe und ersetze die verschlissenen Teile.", "Sprawdź i wymień zużyte części.", "Inspecciona y sustituye las piezas desgastadas.", "Inspecione e substitua as peças gastas.", "Inspectez et remplacez les pièces usées.", "Controlla e sostituisci le parti usurate."),
        R("Is the brake fluid level between MIN and MAX?", "Fren sıvısı seviyesi MIN ile MAX arasında mı?", "Liegt der Bremsflüssigkeitsstand zwischen MIN und MAX?", "Czy poziom płynu hamulcowego mieści się między MIN a MAX?", "¿Está el nivel del líquido de frenos entre MIN y MAX?", "O nível do líquido dos travões está entre MIN e MAX?", "Le niveau de liquide de frein est-il entre MIN et MAX ?", "Il livello del liquido dei freni è tra MIN e MAX?"),
        R("Is the brake pedal firm and does it hold without slowly sinking?", "Fren pedalı sert mi ve yavaşça çökmeden duruyor mu?", "Ist das Bremspedal fest und hält es, ohne langsam durchzusinken?", "Czy pedał hamulca jest twardy i trzyma, bez powolnego opadania?", "¿Está firme el pedal de freno y se mantiene sin hundirse lentamente?", "O pedal do travão está firme e mantém-se sem afundar lentamente?", "La pédale de frein est-elle ferme et tient-elle sans s’enfoncer lentement ?", "Il pedale del freno è fermo e tiene senza affondare lentamente?"),
        R("Is the catalytic converter (and DPF on a diesel) still fitted?", "Katalitik konvertör (dizelde DPF) hâlâ takılı mı?", "Ist der Katalysator (und bei Diesel der DPF) noch verbaut?", "Czy katalizator (a w dieslu DPF) nadal jest zamontowany?", "¿Sigue montado el catalizador (y el DPF en un diésel)?", "O catalisador (e o DPF num diesel) ainda está montado?", "Le catalyseur (et le FAP sur un diesel) est-il toujours monté ?", "Il catalizzatore (e il DPF su un diesel) è ancora montato?"),
        R("Is the exhaust firmly mounted and not hanging down?", "Egzoz sıkıca monte edilmiş ve sarkmıyor mu?", "Ist der Auspuff fest montiert und hängt nicht herunter?", "Czy wydech jest mocno zamontowany i nie zwisa?", "¿Está el escape bien sujeto y sin colgar?", "O escape está bem fixo e não pende?", "L’échappement est-il bien fixé et ne pend-il pas ?", "Lo scarico è ben fissato e non penzola?"),
        R("Is the exhaust no louder than normal and free of rattles?", "Egzoz normalden gürültülü değil ve tıkırtısız mı?", "Ist der Auspuff nicht lauter als normal und frei von Klappern?", "Czy wydech nie jest głośniejszy niż zwykle i nie grzechocze?", "¿Está el escape sin más ruido de lo normal y sin vibraciones?", "O escape não está mais ruidoso do que o normal e sem vibrações?", "L’échappement n’est-il pas plus bruyant que la normale et sans cliquetis ?", "Lo scarico non è più rumoroso del normale e senza vibrazioni?"),
        R("Is the steering free of knocks, clunks and tight spots?", "Direksiyonda vuruntu, tıkırtı ve sıkışma yok mu?", "Ist die Lenkung frei von Klopfen, Poltern und schwergängigen Stellen?", "Czy układ kierowniczy jest wolny od stuków, łomotów i oporów?", "¿Está la dirección libre de golpes, ruidos secos y puntos duros?", "A direção está livre de pancadas, estalidos e pontos duros?", "La direction est-elle exempte de cognements, claquements et points durs ?", "Lo sterzo è privo di colpi, rumori sordi e punti duri?"),
        R("Is the steering free play small?", "Direksiyon boşluğu az mı?", "Ist das Lenkspiel gering?", "Czy luz kierownicy jest mały?", "¿Es pequeña la holgura de la dirección?", "A folga da direção é pequena?", "Le jeu de direction est-il faible ?", "Il gioco dello sterzo è ridotto?"),
        R("Is the tread depth above 1.6 mm on every tire?", "Her lastikte diş derinliği 1,6 mm’nin üzerinde mi?", "Liegt die Profiltiefe bei jedem Reifen über 1,6 mm?", "Czy głębokość bieżnika na każdej oponie przekracza 1,6 mm?", "¿Es la profundidad del dibujo superior a 1,6 mm en cada neumático?", "A profundidade do piso é superior a 1,6 mm em cada pneu?", "La profondeur de sculpture dépasse-t-elle 1,6 mm sur chaque pneu ?", "La profondità del battistrada supera 1,6 mm su ogni pneumatico?"),
        R("Is the VIN on the body readable and does it match the registration certificate?", "Kaportadaki VIN okunabilir mi ve ruhsatla eşleşiyor mu?", "Ist die VIN an der Karosserie lesbar und stimmt sie mit dem Fahrzeugschein überein?", "Czy VIN na nadwoziu jest czytelny i zgadza się z dowodem rejestracyjnym?", "¿Es legible el VIN de la carrocería y coincide con el permiso de circulación?", "O VIN na carroçaria é legível e coincide com o documento de matrícula?", "Le VIN sur la carrosserie est-il lisible et correspond-il à la carte grise ?", "Il VIN sulla carrozzeria è leggibile e corrisponde al libretto di circolazione?"),
        R("Is the windshield free of cracks and chips on the driver's side?", "Ön cam sürücü tarafında çatlak ve çentikten arınmış mı?", "Ist die Windschutzscheibe auf der Fahrerseite frei von Rissen und Steinschlägen?", "Czy przednia szyba po stronie kierowcy jest wolna od pęknięć i odprysków?", "¿Está el parabrisas libre de grietas y picaduras en el lado del conductor?", "O para-brisas está sem fissuras e picos do lado do condutor?", "Le pare-brise est-il exempt de fissures et d’impacts côté conducteur ?", "Il parabrezza è privo di crepe e scheggiature dal lato guida?"),
        R("Is there a fire extinguisher that is still in date?", "Süresi geçmemiş bir yangın söndürücü var mı?", "Gibt es einen Feuerlöscher, der noch gültig ist?", "Czy jest gaśnica z ważną datą?", "¿Hay un extintor que siga en fecha?", "Existe um extintor ainda dentro da validade?", "Y a-t-il un extincteur encore valide ?", "C’è un estintore ancora in corso di validità?"),
        R("Is there a first-aid kit in the car?", "Araçta ilk yardım çantası var mı?", "Befindet sich ein Verbandkasten im Fahrzeug?", "Czy w aucie jest apteczka?", "¿Hay un botiquín en el coche?", "Existe uma caixa de primeiros socorros no carro?", "Y a-t-il une trousse de secours dans la voiture ?", "C’è una cassetta di pronto soccorso nell’auto?"),
        R("Is there a warning triangle in the car?", "Araçta reflektör var mı?", "Befindet sich ein Warndreieck im Fahrzeug?", "Czy w aucie jest trójkąt ostrzegawczy?", "¿Hay un triángulo de emergencia en el coche?", "Existe um triângulo de sinalização no carro?", "Y a-t-il un triangle de signalisation dans la voiture ?", "C’è un triangolo di emergenza nell’auto?"),
        R("It is usually in the boot, often clipped to the tailgate.", "Genellikle bagajdadır, çoğunlukla bagaj kapağına klipslenmiştir.", "Er liegt meist im Kofferraum, oft an der Heckklappe befestigt.", "Zwykle jest w bagażniku, często przypięty do klapy.", "Suele estar en el maletero, a menudo sujeto a la tapa.", "Costuma estar na bagageira, muitas vezes preso à tampa.", "Il se trouve généralement dans le coffre, souvent fixé au hayon.", "Di solito è nel bagagliaio, spesso fissato al portellone."),
        R("Knocking or binding in the steering", "Direksiyonda vuruntu veya sıkışma", "Klopfen oder Schwergängigkeit in der Lenkung", "Stuki lub zacinanie się układu kierowniczego", "Golpeteo o agarrotamiento en la dirección", "Pancadas ou dureza na direção", "Cognements ou points durs dans la direction", "Colpi o durezza nello sterzo"),
        R("Knocking or humming from the running gear", "Alt takımdan vuruntu veya uğultu", "Klopfen oder Brummen vom Fahrwerk", "Stuki lub buczenie z zawieszenia", "Golpeteo o zumbido del tren de rodaje", "Pancadas ou zumbido da suspensão", "Cognements ou ronflement du train roulant", "Colpi o ronzio dal gruppo sospensioni"),
        R("Look at the rubber hose at each wheel: it must not be cracked, swollen or wet. A wet patch inside the wheel also means a leak.", "Her tekerlekteki lastik hortuma bak: çatlak, şişmiş veya ıslak olmamalı. Tekerleğin içindeki ıslak bir leke de sızıntı demektir.", "Sieh dir den Gummischlauch an jedem Rad an: Er darf nicht rissig, aufgequollen oder nass sein. Eine nasse Stelle im Rad bedeutet ebenfalls ein Leck.", "Sprawdź gumowy wąż przy każdym kole: nie może być popękany, spęczniały ani mokry. Mokra plama wewnątrz koła też oznacza wyciek.", "Mira el manguito de goma de cada rueda: no debe estar agrietado, hinchado ni mojado. Una mancha húmeda dentro de la rueda también indica fuga.", "Veja a mangueira de borracha em cada roda: não pode estar fissurada, inchada ou molhada. Uma mancha húmida dentro da roda também indica fuga.", "Regardez le flexible en caoutchouc de chaque roue : il ne doit pas être fissuré, gonflé ou humide. Une tache humide à l’intérieur de la roue indique aussi une fuite.", "Guarda il tubo di gomma su ogni ruota: non deve essere crepato, gonfio o bagnato. Anche una macchia umida all’interno della ruota indica una perdita."),
        R("Look at the tank and lines under the car near the rear wheels and in the engine bay. Fuel drips or a constant smell are dangerous.", "Aracın altında arka tekerlekler yakınındaki depoya ve hatlara ve motor bölmesine bak. Yakıt damlaması veya sürekli koku tehlikelidir.", "Sieh dir den Tank und die Leitungen unter dem Fahrzeug nahe den Hinterrädern und im Motorraum an. Kraftstofftropfen oder ein ständiger Geruch sind gefährlich.", "Sprawdź zbiornik i przewody pod autem przy tylnych kołach oraz w komorze silnika. Kapanie paliwa lub stały zapach są niebezpieczne.", "Mira el depósito y las tuberías bajo el coche cerca de las ruedas traseras y en el vano motor. Goteo de combustible o olor constante son peligrosos.", "Veja o depósito e as condutas debaixo do carro perto das rodas traseiras e no compartimento do motor. Pingos de combustível ou cheiro constante são perigosos.", "Regardez le réservoir et les conduites sous la voiture près des roues arrière et dans le compartiment moteur. Des gouttes de carburant ou une odeur constante sont dangereuses.", "Guarda il serbatoio e le tubazioni sotto l’auto vicino alle ruote posteriori e nel vano motore. Gocciolamenti di carburante o un odore costante sono pericolosi."),
        R("Look between the wheel spokes: pad friction material should be thicker than 3 mm, with no deep grooves on the disc or a high lip at its edge. Squealing when braking is a wear sign.", "Jant kolları arasından bak: balata sürtünme malzemesi 3 mm’den kalın olmalı, diskte derin oluk veya kenarında yüksek bir çıkıntı olmamalı. Fren yaparken ıslık sesi aşınma belirtisidir.", "Sieh zwischen den Radspeichen hindurch: Das Belagmaterial sollte dicker als 3 mm sein, ohne tiefe Riefen auf der Scheibe oder hohen Rand an der Kante. Quietschen beim Bremsen ist ein Verschleißzeichen.", "Zajrzyj między szprychy: materiał cierny klocka powinien mieć ponad 3 mm, bez głębokich rowków na tarczy ani wysokiego rantu na jej krawędzi. Pisk przy hamowaniu to oznaka zużycia.", "Mira entre los radios de la rueda: el material de fricción de la pastilla debe tener más de 3 mm, sin surcos profundos en el disco ni un reborde alto en su borde. El chirrido al frenar es señal de desgaste.", "Veja entre os raios da roda: o material de fricção da pastilha deve ter mais de 3 mm, sem sulcos profundos no disco nem rebordo alto na borda. Guinchar ao travar é sinal de desgaste.", "Regardez entre les branches de la jante : la garniture de plaquette doit faire plus de 3 mm, sans rainures profondes sur le disque ni rebord élevé sur son bord. Un grincement au freinage est un signe d’usure.", "Guarda tra i raggi della ruota: il materiale d’attrito della pastiglia deve essere più spesso di 3 mm, senza solchi profondi sul disco né un bordo alto. Lo stridio in frenata è segno di usura."),
        R("Low beam not working", "Kısa far çalışmıyor", "Abblendlicht funktioniert nicht", "Światło mijania nie działa", "La luz de cruce no funciona", "O médio não funciona", "Le feu de croisement ne fonctionne pas", "L’anabbagliante non funziona"),
        R("Make sure it is complete and nothing in it has expired.", "Eksiksiz olduğundan ve içindeki hiçbir şeyin süresinin dolmadığından emin ol.", "Stelle sicher, dass er vollständig ist und nichts darin abgelaufen ist.", "Upewnij się, że jest kompletna i nic w niej nie jest przeterminowane.", "Asegúrate de que esté completo y de que nada haya caducado.", "Certifique-se de que está completa e nada caducou.", "Assurez-vous qu’elle est complète et que rien n’est périmé.", "Assicurati che sia completa e che nulla sia scaduto."),
        R("Mirror broken or loose", "Ayna kırık veya gevşek", "Spiegel gebrochen oder lose", "Lusterko pęknięte lub luźne", "Espejo roto o suelto", "Espelho partido ou solto", "Rétroviseur cassé ou desserré", "Specchietto rotto o allentato"),
        R("Mismatched tires on one axle", "Aynı akstaki lastikler uyumsuz", "Ungleiche Reifen auf einer Achse", "Niedopasowane opony na jednej osi", "Neumáticos distintos en un mismo eje", "Pneus diferentes no mesmo eixo", "Pneus différents sur un même essieu", "Pneumatici diversi sullo stesso asse"),
        R("No black, blue or thick white smoke when revving hard?", "Sert gaz verirken siyah, mavi veya yoğun beyaz duman yok mu?", "Kein schwarzer, blauer oder dicker weißer Rauch beim kräftigen Gasgeben?", "Brak czarnego, niebieskiego lub gęstego białego dymu przy mocnym gazowaniu?", "¿No sale humo negro, azul o blanco espeso al acelerar a fondo?", "Sem fumo preto, azul ou branco denso ao acelerar a fundo?", "Pas de fumée noire, bleue ou blanche épaisse en accélérant fort ?", "Nessun fumo nero, blu o bianco denso accelerando forte?"),
        R("No fuel smell and no fuel leaks?", "Yakıt kokusu ve yakıt sızıntısı yok mu?", "Kein Kraftstoffgeruch und keine Kraftstofflecks?", "Brak zapachu paliwa i wycieków paliwa?", "¿Sin olor a combustible ni fugas de combustible?", "Sem cheiro a combustível e sem fugas de combustível?", "Pas d’odeur de carburant ni de fuites de carburant ?", "Nessun odore di carburante e nessuna perdita di carburante?"),
        R("No knocks over bumps and no humming from the wheels?", "Tümseklerde vuruntu ve tekerleklerden uğultu yok mu?", "Kein Klopfen über Unebenheiten und kein Brummen von den Rädern?", "Brak stuków na nierównościach i buczenia kół?", "¿Sin golpes en los baches y sin zumbido de las ruedas?", "Sem pancadas nas lombas e sem zumbido das rodas?", "Pas de cognements sur les bosses ni de ronflement des roues ?", "Nessun colpo sulle buche e nessun ronzio dalle ruote?"),
        R("No mirror may be broken, and none may shake or move by itself while driving.", "Hiçbir ayna kırık olmamalı ve sürüş sırasında kendiliğinden sallanmamalı veya oynamamalı.", "Kein Spiegel darf gebrochen sein, und keiner darf während der Fahrt wackeln oder sich von selbst verstellen.", "Żadne lusterko nie może być pęknięte ani drgać czy przesuwać się samo podczas jazdy.", "Ningún espejo puede estar roto ni vibrar o moverse solo mientras se conduce.", "Nenhum espelho pode estar partido, nem tremer ou mexer-se sozinho durante a condução.", "Aucun rétroviseur ne doit être cassé, ni vibrer ou bouger tout seul en roulant.", "Nessuno specchietto può essere rotto, né vibrare o muoversi da solo durante la guida."),
        R("No oil, transmission fluid or coolant dripping?", "Yağ, şanzıman yağı veya soğutma suyu damlamıyor mu?", "Tropft kein Öl, Getriebeöl oder Kühlmittel?", "Czy nic nie kapie: olej, olej przekładniowy ani płyn chłodzący?", "¿No gotea aceite, líquido de transmisión ni refrigerante?", "Não pinga óleo, óleo da transmissão nem líquido de arrefecimento?", "Pas de fuite d’huile, d’huile de transmission ou de liquide de refroidissement ?", "Non gocciolano olio, olio del cambio o liquido di raffreddamento?"),
        R("Number plate damaged or unreadable", "Plaka hasarlı veya okunamıyor", "Kennzeichen beschädigt oder unlesbar", "Uszkodzona lub nieczytelna tablica rejestracyjna", "Matrícula dañada o ilegible", "Matrícula danificada ou ilegível", "Plaque d’immatriculation endommagée ou illisible", "Targa danneggiata o illeggibile"),
        R("Number plate light not working", "Plaka lambası çalışmıyor", "Kennzeichenbeleuchtung funktioniert nicht", "Oświetlenie tablicy rejestracyjnej nie działa", "La luz de la matrícula no funciona", "A luz da matrícula não funciona", "L’éclairage de plaque ne fonctionne pas", "La luce targa non funziona"),
        R("On an empty straight road, brake hard from 40–50 km/h holding the wheel lightly. Pulling means unequal left/right braking force. On the test bench this difference on one axle must not exceed 30%.", "Boş, düz bir yolda direksiyonu hafifçe tutarak 40–50 km/sa hızdan sert fren yap. Çekme, sol/sağ fren kuvvetinin eşit olmadığı anlamına gelir. Test tezgâhında bir akstaki bu fark %30’u geçmemelidir.", "Bremse auf einer leeren, geraden Straße aus 40–50 km/h kräftig und halte das Lenkrad locker. Ziehen bedeutet ungleiche Bremskraft links/rechts. Auf dem Prüfstand darf dieser Unterschied an einer Achse 30 % nicht überschreiten.", "Na pustej prostej drodze zahamuj mocno z 40–50 km/h, trzymając lekko kierownicę. Ściąganie oznacza nierówną siłę hamowania lewej i prawej strony. Na hamowni ta różnica na jednej osi nie może przekraczać 30%.", "En una carretera recta y vacía, frena fuerte desde 40–50 km/h sujetando el volante con suavidad. Si tira, la fuerza de frenado izquierda/derecha es desigual. En el banco de pruebas esta diferencia en un eje no debe superar el 30 %.", "Numa estrada reta e vazia, trave a fundo a 40–50 km/h segurando o volante com suavidade. Se puxar, a força de travagem esquerda/direita é desigual. No banco de ensaios esta diferença num eixo não pode exceder 30%.", "Sur une route droite et vide, freinez fort depuis 40–50 km/h en tenant légèrement le volant. Si elle tire, la force de freinage gauche/droite est inégale. Au banc d’essai, cet écart sur un essieu ne doit pas dépasser 30 %.", "Su una strada dritta e vuota, frena forte da 40–50 km/h tenendo il volante leggero. Se tira, la forza frenante sinistra/destra è disuguale. Al banco prova questa differenza su un asse non deve superare il 30%."),
        R("On level ground, compare the gap between wheel and arch at all four corners. A broken spring is often visible from inside the wheel.", "Düz zeminde dört köşedeki tekerlek ile çamurluk arasındaki boşluğu karşılaştır. Kırık bir yay çoğu zaman tekerleğin içinden görülür.", "Vergleiche auf ebenem Boden den Abstand zwischen Rad und Radkasten an allen vier Ecken. Eine gebrochene Feder ist oft von innen im Rad zu sehen.", "Na równym podłożu porównaj odstęp między kołem a nadkolem we wszystkich czterech narożnikach. Pęknięta sprężyna jest często widoczna od wewnątrz koła.", "En suelo llano, compara la distancia entre rueda y paso de rueda en las cuatro esquinas. Un muelle roto suele verse desde el interior de la rueda.", "Em piso plano, compare a distância entre a roda e a cava nos quatro cantos. Uma mola partida costuma ver-se do interior da roda.", "Sur sol plat, comparez l’écart entre la roue et le passage de roue aux quatre coins. Un ressort cassé est souvent visible de l’intérieur de la roue.", "Su terreno piano, confronta lo spazio tra ruota e passaruota ai quattro angoli. Una molla rotta spesso si vede dall’interno della ruota."),
        R("Parking brake does not hold", "El freni tutmuyor", "Feststellbremse hält nicht", "Hamulec postojowy nie trzyma", "El freno de estacionamiento no sujeta", "O travão de estacionamento não segura", "Le frein de stationnement ne tient pas", "Il freno di stazionamento non tiene"),
        R("Power steering fault", "Direksiyon desteği arızası", "Servolenkungsfehler", "Usterka wspomagania kierownicy", "Fallo de la dirección asistida", "Avaria da direção assistida", "Défaut de direction assistée", "Guasto al servosterzo"),
        R("Press the triangle button. All indicators must flash together.", "Üçgen düğmesine bas. Tüm sinyaller birlikte yanıp sönmeli.", "Drücke die Dreieck-Taste. Alle Blinker müssen gemeinsam blinken.", "Naciśnij przycisk trójkąta. Wszystkie kierunkowskazy muszą mrugać razem.", "Pulsa el botón del triángulo. Todos los intermitentes deben parpadear a la vez.", "Prima o botão do triângulo. Todos os piscas têm de piscar em conjunto.", "Appuyez sur le bouton triangle. Tous les clignotants doivent clignoter ensemble.", "Premi il pulsante del triangolo. Tutti gli indicatori devono lampeggiare insieme."),
        R("Pull each belt out fully, buckle it and tug sharply: it must lock. The webbing must not be torn or badly frayed.", "Her kemeri tamamen çek, tak ve ani çek: kilitlenmeli. Kayış yırtık veya fena halde yıpranmış olmamalı.", "Ziehe jeden Gurt ganz heraus, schließe ihn und ziehe ruckartig: Er muss blockieren. Das Gurtband darf nicht eingerissen oder stark ausgefranst sein.", "Wyciągnij każdy pas do końca, zapnij i szarpnij: musi się zablokować. Taśma nie może być podarta ani mocno postrzępiona.", "Saca cada cinturón del todo, abróchalo y tira con fuerza: debe bloquearse. La cinta no debe estar rota ni muy deshilachada.", "Puxe cada cinto totalmente, aperte-o e puxe com força: tem de bloquear. A fita não pode estar rasgada nem muito desfiada.", "Sortez chaque ceinture entièrement, bouclez-la et tirez sèchement : elle doit se bloquer. La sangle ne doit pas être déchirée ni très effilochée.", "Estrai completamente ogni cintura, allacciala e tira di scatto: deve bloccarsi. Il nastro non deve essere strappato né molto sfilacciato."),
        R("Push down each corner and let go: it should settle after 1–2 bounces. An oily shock body means it is leaking.", "Her köşeyi aşağı bas ve bırak: 1–2 zıplamadan sonra yerine oturmalı. Yağlı bir amortisör gövdesi sızdırdığı anlamına gelir.", "Drücke jede Ecke nach unten und lasse los: Sie sollte nach 1–2 Wippern zur Ruhe kommen. Ein öliger Dämpferkörper bedeutet, dass er undicht ist.", "Dociśnij każdy narożnik i puść: powinien się uspokoić po 1–2 odbiciach. Oleisty korpus amortyzatora oznacza wyciek.", "Presiona cada esquina y suelta: debe asentarse tras 1–2 rebotes. Un cuerpo de amortiguador aceitoso indica que pierde.", "Pressione cada canto e solte: deve assentar após 1–2 oscilações. Um corpo de amortecedor oleoso indica fuga.", "Appuyez sur chaque coin et relâchez : il doit se stabiliser après 1–2 rebonds. Un corps d’amortisseur huileux indique une fuite.", "Premi ogni angolo e rilascia: deve assestarsi dopo 1–2 rimbalzi. Un corpo ammortizzatore unto indica una perdita."),
        R("Put your phone behind the car and record a video while pressing the pedal, or check the reflection on a wall in the evening. The third, high brake light must work too.", "Telefonunu aracın arkasına koy ve pedala basarken video çek ya da akşam duvardaki yansımaya bak. Üçüncü, yüksek fren lambası da çalışmalı.", "Stelle dein Handy hinter das Fahrzeug und nimm ein Video auf, während du das Pedal trittst, oder prüfe abends die Spiegelung an einer Wand. Auch das dritte, hohe Bremslicht muss funktionieren.", "Połóż telefon za autem i nagraj wideo podczas naciskania pedału lub sprawdź wieczorem odbicie na ścianie. Trzecie, wysokie światło hamowania też musi działać.", "Pon el teléfono detrás del coche y graba un vídeo mientras pisas el pedal, o comprueba el reflejo en una pared por la tarde. La tercera luz de freno, la alta, también debe funcionar.", "Ponha o telemóvel atrás do carro e grave um vídeo enquanto pisa o pedal, ou verifique o reflexo numa parede ao anoitecer. A terceira luz de travagem, a alta, também tem de funcionar.", "Posez votre téléphone derrière la voiture et filmez en appuyant sur la pédale, ou vérifiez le reflet sur un mur le soir. Le troisième feu stop, en hauteur, doit aussi fonctionner.", "Metti il telefono dietro l’auto e registra un video mentre premi il pedale, oppure controlla il riflesso su un muro la sera. Deve funzionare anche la terza luce di stop, quella alta."),
        R("Read the ABS module codes and fix the cause.", "ABS modülü kodlarını oku ve nedeni gider.", "Lies die Codes des ABS-Moduls und behebe die Ursache.", "Odczytaj kody modułu ABS i usuń przyczynę.", "Lee los códigos del módulo ABS y corrige la causa.", "Leia os códigos do módulo ABS e corrija a causa.", "Lisez les codes du module ABS et corrigez la cause.", "Leggi i codici del modulo ABS e correggi la causa."),
        R("Read the airbag module codes and fix the cause.", "Hava yastığı modülü kodlarını oku ve nedeni gider.", "Lies die Codes des Airbag-Moduls und behebe die Ursache.", "Odczytaj kody modułu poduszek powietrznych i usuń przyczynę.", "Lee los códigos del módulo del airbag y corrige la causa.", "Leia os códigos do módulo do airbag e corrija a causa.", "Lisez les codes du module airbag et corrigez la cause.", "Leggi i codici del modulo airbag e correggi la causa."),
        R("Refit the catalyst or DPF.", "Katalizörü veya DPF’yi yeniden tak.", "Katalysator oder DPF wieder einbauen.", "Zamontuj ponownie katalizator lub DPF.", "Vuelve a montar el catalizador o el DPF.", "Volte a montar o catalisador ou o DPF.", "Remontez le catalyseur ou le FAP.", "Rimonta il catalizzatore o il DPF."),
        R("Remove the film from the windshield and front side windows.", "Ön camdan ve ön yan camlardan filmi kaldır.", "Entferne die Folie von Windschutzscheibe und vorderen Seitenscheiben.", "Usuń folię z przedniej szyby i przednich szyb bocznych.", "Quita la lámina del parabrisas y de las ventanillas delanteras.", "Retire a película do para-brisas e dos vidros laterais da frente.", "Retirez le film du pare-brise et des vitres latérales avant.", "Rimuovi la pellicola dal parabrezza e dai finestrini anteriori."),
        R("Repair or replace the silencer.", "Susturucuyu onar veya değiştir.", "Schalldämpfer reparieren oder ersetzen.", "Napraw lub wymień tłumik.", "Repara o sustituye el silenciador.", "Repare ou substitua o silenciador.", "Réparez ou remplacez le silencieux.", "Ripara o sostituisci il silenziatore."),
        R("Repair or weld the affected areas.", "Etkilenen bölgeleri onar veya kaynakla.", "Betroffene Stellen reparieren oder schweißen.", "Napraw lub zespawaj uszkodzone miejsca.", "Repara o suelda las zonas afectadas.", "Repare ou solde as zonas afetadas.", "Réparez ou soudez les zones touchées.", "Ripara o salda le zone interessate."),
        R("Repair the leak.", "Sızıntıyı onar.", "Das Leck reparieren.", "Napraw wyciek.", "Repara la fuga.", "Repare a fuga.", "Réparez la fuite.", "Ripara la perdita."),
        R("Replace the belt or the buckle.", "Kemeri veya tokayı değiştir.", "Gurt oder Schloss ersetzen.", "Wymień pas lub klamrę.", "Sustituye el cinturón o la hebilla.", "Substitua o cinto ou a fivela.", "Remplacez la ceinture ou la boucle.", "Sostituisci la cintura o la fibbia."),
        R("Replace the blades and refill or repair the washer.", "Lastikleri değiştir ve yıkama suyunu doldur veya onar.", "Wischerblätter ersetzen und die Waschanlage auffüllen oder reparieren.", "Wymień pióra wycieraczek i uzupełnij lub napraw spryskiwacz.", "Sustituye las escobillas y rellena o repara el lavaparabrisas.", "Substitua as escovas e encha ou repare o esguicho.", "Remplacez les balais et remplissez ou réparez le lave-glace.", "Sostituisci le spazzole e riempi o ripara lo spruzzatore."),
        R("Replace the bulb or check the fuse.", "Ampulü değiştir veya sigortayı kontrol et.", "Leuchtmittel ersetzen oder Sicherung prüfen.", "Wymień żarówkę lub sprawdź bezpiecznik.", "Sustituye la bombilla o revisa el fusible.", "Substitua a lâmpada ou verifique o fusível.", "Remplacez l’ampoule ou vérifiez le fusible.", "Sostituisci la lampadina o controlla il fusibile."),
        R("Replace the bulb or the pedal switch.", "Ampulü veya pedal anahtarını değiştir.", "Leuchtmittel oder Pedalschalter ersetzen.", "Wymień żarówkę lub włącznik pedału.", "Sustituye la bombilla o el interruptor del pedal.", "Substitua a lâmpada ou o interruptor do pedal.", "Remplacez l’ampoule ou le contacteur de pédale.", "Sostituisci la lampadina o l’interruttore del pedale."),
        R("Replace the bulb.", "Ampulü değiştir.", "Leuchtmittel ersetzen.", "Wymień żarówkę.", "Sustituye la bombilla.", "Substitua a lâmpada.", "Remplacez l’ampoule.", "Sostituisci la lampadina."),
        R("Replace the damaged hose or pipe.", "Hasarlı hortumu veya boruyu değiştir.", "Beschädigten Schlauch oder beschädigte Leitung ersetzen.", "Wymień uszkodzony wąż lub przewód.", "Sustituye el manguito o tubo dañado.", "Substitua a mangueira ou o tubo danificado.", "Remplacez le flexible ou la conduite endommagés.", "Sostituisci il flessibile o il tubo danneggiato."),
        R("Replace the hangers or the damaged pipe.", "Askıları veya hasarlı boruyu değiştir.", "Aufhänger oder das beschädigte Rohr ersetzen.", "Wymień zawieszenia lub uszkodzoną rurę.", "Sustituye los soportes o el tubo dañado.", "Substitua os suportes ou o tubo danificado.", "Remplacez les supports ou le tuyau endommagé.", "Sostituisci i supporti o il tubo danneggiato."),
        R("Replace the mirror or its glass.", "Aynayı veya camını değiştir.", "Spiegel oder Spiegelglas ersetzen.", "Wymień lusterko lub jego szkło.", "Sustituye el espejo o su cristal.", "Substitua o espelho ou o respetivo vidro.", "Remplacez le rétroviseur ou sa glace.", "Sostituisci lo specchietto o il suo vetro."),
        R("Replace the pads, and the discs if needed.", "Balataları ve gerekirse diskleri değiştir.", "Beläge und bei Bedarf die Scheiben ersetzen.", "Wymień klocki, a w razie potrzeby także tarcze.", "Sustituye las pastillas y, si hace falta, los discos.", "Substitua as pastilhas e, se necessário, os discos.", "Remplacez les plaquettes et, si nécessaire, les disques.", "Sostituisci le pastiglie e, se serve, i dischi."),
        R("Replace the shock absorbers in pairs.", "Amortisörleri çift olarak değiştir.", "Stoßdämpfer paarweise ersetzen.", "Wymieniaj amortyzatory parami.", "Sustituye los amortiguadores por pares.", "Substitua os amortecedores aos pares.", "Remplacez les amortisseurs par paires.", "Sostituisci gli ammortizzatori in coppia."),
        R("Replace the springs in pairs.", "Yayları çift olarak değiştir.", "Federn paarweise ersetzen.", "Wymieniaj sprężyny parami.", "Sustituye los muelles por pares.", "Substitua as molas aos pares.", "Remplacez les ressorts par paires.", "Sostituisci le molle in coppia."),
        R("Replace the tire immediately.", "Lastiği hemen değiştir.", "Reifen sofort ersetzen.", "Natychmiast wymień oponę.", "Sustituye el neumático de inmediato.", "Substitua o pneu de imediato.", "Remplacez le pneu immédiatement.", "Sostituisci subito lo pneumatico."),
        R("Replace the tires.", "Lastikleri değiştir.", "Reifen ersetzen.", "Wymień opony.", "Sustituye los neumáticos.", "Substitua os pneus.", "Remplacez les pneus.", "Sostituisci gli pneumatici."),
        R("Replace the windshield or repair the chip before it spreads.", "Ön camı değiştir veya çentiği yayılmadan onar.", "Windschutzscheibe ersetzen oder den Steinschlag reparieren, bevor er sich ausbreitet.", "Wymień szybę lub napraw odprysk, zanim się rozszerzy.", "Sustituye el parabrisas o repara la picadura antes de que se extienda.", "Substitua o para-brisas ou repare o pico antes que se espalhe.", "Remplacez le pare-brise ou réparez l’impact avant qu’il ne s’étende.", "Sostituisci il parabrezza o ripara la scheggiatura prima che si estenda."),
        R("Replace the worn steering parts.", "Aşınmış direksiyon parçalarını değiştir.", "Verschlissene Lenkungsteile ersetzen.", "Wymień zużyte części układu kierowniczego.", "Sustituye las piezas de dirección desgastadas.", "Substitua as peças de direção gastas.", "Remplacez les pièces de direction usées.", "Sostituisci le parti dello sterzo usurate."),
        R("Resolve the mismatch with the registration office before the inspection.", "Muayeneden önce uyuşmazlığı tescil bürosuyla çöz.", "Kläre die Abweichung vor der Inspektion mit der Zulassungsstelle.", "Wyjaśnij niezgodność z urzędem rejestracji przed przeglądem.", "Resuelve la discrepancia con la oficina de matriculación antes de la inspección.", "Resolva a discrepância com o serviço de registo antes da inspeção.", "Réglez la divergence avec le service d’immatriculation avant le contrôle.", "Risolvi la discrepanza con l’ufficio di immatricolazione prima della revisione."),
        R("Reversing light not working", "Geri vites lambası çalışmıyor", "Rückfahrlicht funktioniert nicht", "Światło cofania nie działa", "La luz de marcha atrás no funciona", "A luz de marcha-atrás não funciona", "Le feu de recul ne fonctionne pas", "La luce di retromarcia non funziona"),
        R("Safety equipment", "Güvenlik ekipmanı", "Sicherheitsausrüstung", "Wyposażenie bezpieczeństwa", "Equipo de seguridad", "Equipamento de segurança", "Équipement de sécurité", "Dotazioni di sicurezza"),
        R("Seat belt faulty", "Emniyet kemeri arızalı", "Sicherheitsgurt defekt", "Uszkodzony pas bezpieczeństwa", "Cinturón de seguridad defectuoso", "Cinto de segurança avariado", "Ceinture de sécurité défectueuse", "Cintura di sicurezza difettosa"),
        R("Seat loose", "Koltuk gevşek", "Sitz lose", "Luźny fotel", "Asiento suelto", "Banco solto", "Siège desserré", "Sedile allentato"),
        R("Secure or replace the damaged part.", "Hasarlı parçayı sabitle veya değiştir.", "Beschädigtes Teil befestigen oder ersetzen.", "Zamocuj lub wymień uszkodzoną część.", "Fija o sustituye la pieza dañada.", "Fixe ou substitua a peça danificada.", "Fixez ou remplacez la pièce endommagée.", "Fissa o sostituisci la parte danneggiata."),
        R("Secure the seat.", "Koltuğu sabitle.", "Sitz befestigen.", "Zamocuj fotel.", "Fija el asiento.", "Fixe o banco.", "Fixez le siège.", "Fissa il sedile."),
        R("Shake the bumpers. They must not move, and broken areas must not have sharp edges.", "Tamponları salla. Hareket etmemeli ve kırık yerlerde keskin kenar olmamalı.", "Rüttle an den Stoßfängern. Sie dürfen sich nicht bewegen, und gebrochene Stellen dürfen keine scharfen Kanten haben.", "Potrząśnij zderzakami. Nie mogą się ruszać, a pęknięte miejsca nie mogą mieć ostrych krawędzi.", "Sacude los parachoques. No deben moverse y las zonas rotas no deben tener bordes afilados.", "Abane os para-choques. Não podem mexer e as zonas partidas não podem ter arestas vivas.", "Secouez les pare-chocs. Ils ne doivent pas bouger et les zones cassées ne doivent pas avoir d’arêtes vives.", "Scuoti i paraurti. Non devono muoversi e le zone rotte non devono avere spigoli vivi."),
        R("Shock absorber worn or leaking", "Amortisör aşınmış veya sızdırıyor", "Stoßdämpfer verschlissen oder undicht", "Zużyty lub cieknący amortyzator", "Amortiguador desgastado o con fugas", "Amortecedor gasto ou com fugas", "Amortisseur usé ou qui fuit", "Ammortizzatore usurato o con perdite"),
        R("Sit down and rock back and forth. The seat must be locked on its rails.", "Otur ve ileri geri salla. Koltuk raylarında kilitli olmalı.", "Setze dich und wippe vor und zurück. Der Sitz muss auf den Schienen eingerastet sein.", "Usiądź i pokołysz się w przód i w tył. Fotel musi być zablokowany na szynach.", "Siéntate y balancéate adelante y atrás. El asiento debe estar bloqueado en sus raíles.", "Sente-se e balance para a frente e para trás. O banco tem de estar bloqueado nas guias.", "Asseyez-vous et balancez-vous d’avant en arrière. Le siège doit être verrouillé sur ses rails.", "Siediti e dondola avanti e indietro. Il sedile deve essere bloccato sulle guide."),
        R("Sit in the driver's seat and look at the wiper area. No crack is allowed there, not even a small chip. A small chip on the passenger side is usually not a problem.", "Sürücü koltuğuna otur ve silecek alanına bak. Orada çatlağa, küçük bir çentiğe bile izin yoktur. Yolcu tarafındaki küçük bir çentik genellikle sorun değildir.", "Setze dich auf den Fahrersitz und sieh dir den Wischerbereich an. Dort ist kein Riss erlaubt, nicht einmal ein kleiner Steinschlag. Ein kleiner Steinschlag auf der Beifahrerseite ist meist kein Problem.", "Usiądź na miejscu kierowcy i spójrz na pole czyszczenia wycieraczek. Nie wolno tam mieć pęknięcia, nawet małego odprysku. Mały odprysk po stronie pasażera zwykle nie jest problemem.", "Siéntate en el asiento del conductor y mira la zona de los limpiaparabrisas. No se permite ninguna grieta allí, ni siquiera una pequeña picadura. Una picadura pequeña en el lado del pasajero normalmente no es problema.", "Sente-se no lugar do condutor e veja a zona dos limpa-para-brisas. Não é permitida qualquer fissura aí, nem um pequeno pico. Um pequeno pico do lado do passageiro normalmente não é problema.", "Asseyez-vous côté conducteur et regardez la zone des essuie-glaces. Aucune fissure n’y est admise, pas même un petit impact. Un petit impact côté passager n’est généralement pas un problème.", "Siediti al posto di guida e guarda l’area dei tergicristalli. Lì non è ammessa alcuna crepa, nemmeno una piccola scheggiatura. Una piccola scheggiatura lato passeggero di solito non è un problema."),
        R("Step back 3–4 m and read it. The plate must not be bent, faded, dirty or covered by a frame.", "3–4 m geri çekil ve oku. Plaka eğri, solmuş, kirli veya çerçeveyle kapalı olmamalı.", "Gehe 3–4 m zurück und lies es. Das Kennzeichen darf nicht verbogen, verblasst, verschmutzt oder von einem Rahmen verdeckt sein.", "Odejdź 3–4 m i przeczytaj ją. Tablica nie może być wygięta, wyblakła, brudna ani zasłonięta ramką.", "Aléjate 3–4 m y léela. La matrícula no debe estar doblada, desteñida, sucia ni tapada por un marco.", "Afaste-se 3–4 m e leia-a. A matrícula não pode estar torta, desbotada, suja ou tapada por uma moldura.", "Reculez de 3–4 m et lisez-la. La plaque ne doit pas être tordue, délavée, sale ou masquée par un cadre.", "Allontanati di 3–4 m e leggila. La targa non deve essere piegata, sbiadita, sporca o coperta da una cornice."),
        R("Stop on a slope, apply the parking brake and select neutral (N on an automatic). The car must not move.", "Bir yokuşta dur, el frenini çek ve boşa al (otomatikte N). Araç hareket etmemeli.", "Halte an einer Steigung, ziehe die Feststellbremse an und wähle Leerlauf (N bei Automatik). Das Fahrzeug darf sich nicht bewegen.", "Zatrzymaj się na pochyłości, zaciągnij hamulec postojowy i wybierz luz (N w automacie). Auto nie może się ruszyć.", "Para en una cuesta, pon el freno de estacionamiento y selecciona punto muerto (N en un automático). El coche no debe moverse.", "Pare numa subida, acione o travão de estacionamento e engate o ponto morto (N num automático). O carro não pode mexer-se.", "Arrêtez-vous en pente, serrez le frein de stationnement et mettez au point mort (N sur une automatique). La voiture ne doit pas bouger.", "Fermati su una pendenza, tira il freno di stazionamento e metti in folle (N su un automatico). L’auto non deve muoversi."),
        R("Switch on left, then right, and walk around the car. Very fast flashing means a bulb is out.", "Önce sol, sonra sağ sinyali aç ve aracın etrafında yürü. Çok hızlı yanıp sönme bir ampulün yandığını gösterir.", "Schalte erst links, dann rechts ein und gehe um das Fahrzeug herum. Sehr schnelles Blinken bedeutet, dass ein Leuchtmittel defekt ist.", "Włącz najpierw lewy, potem prawy kierunkowskaz i obejdź auto dookoła. Bardzo szybkie mruganie oznacza przepaloną żarówkę.", "Activa el intermitente izquierdo y luego el derecho y rodea el coche. Un parpadeo muy rápido indica una bombilla fundida.", "Ligue o pisca esquerdo e depois o direito e dê a volta ao carro. Piscar muito rápido indica uma lâmpada fundida.", "Allumez le clignotant gauche puis le droit et faites le tour de la voiture. Un clignotement très rapide signifie qu’une ampoule est grillée.", "Accendi prima la freccia sinistra poi la destra e fai il giro dell’auto. Un lampeggio molto veloce indica una lampadina bruciata."),
        R("Switch on low, then high beam and look at both headlights from the front.", "Önce kısa, sonra uzun farı aç ve iki farı da önden incele.", "Schalte erst Abblend-, dann Fernlicht ein und sieh dir beide Scheinwerfer von vorn an.", "Włącz najpierw światła mijania, potem drogowe i spójrz na oba reflektory z przodu.", "Activa la luz de cruce y luego la de carretera y mira ambos faros desde delante.", "Ligue o médio e depois o máximo e veja os dois faróis pela frente.", "Allumez les feux de croisement puis de route et regardez les deux phares de face.", "Accendi prima gli anabbaglianti poi gli abbaglianti e guarda entrambi i fari da davanti."),
        R("Switch on the high beams. The blue indicator on the dash must also come on.", "Uzun farları aç. Göstergedeki mavi ikaz da yanmalı.", "Schalte das Fernlicht ein. Die blaue Kontrollleuchte im Armaturenbrett muss ebenfalls angehen.", "Włącz światła drogowe. Niebieska kontrolka na desce rozdzielczej też musi się zapalić.", "Activa las luces de carretera. El indicador azul del cuadro también debe encenderse.", "Ligue os máximos. O indicador azul no painel também tem de acender.", "Allumez les feux de route. Le témoin bleu du tableau de bord doit aussi s’allumer.", "Accendi gli abbaglianti. Deve accendersi anche la spia blu sul cruscotto."),
        R("Switch on the low beams and look from the front, or at the reflection on a wall.", "Kısa farları aç ve önden veya duvardaki yansımadan bak.", "Schalte das Abblendlicht ein und sieh von vorn oder auf die Spiegelung an einer Wand.", "Włącz światła mijania i spójrz z przodu albo na odbicie na ścianie.", "Activa las luces de cruce y mira desde delante o el reflejo en una pared.", "Ligue os médios e veja pela frente ou o reflexo numa parede.", "Allumez les feux de croisement et regardez de face ou le reflet sur un mur.", "Accendi gli anabbaglianti e guarda da davanti o il riflesso su un muro."),
        R("Switch on the side lights and look at the rear plate.", "Park lambalarını aç ve arka plakaya bak.", "Schalte das Standlicht ein und sieh dir das hintere Kennzeichen an.", "Włącz światła postojowe i spójrz na tylną tablicę.", "Activa las luces de posición y mira la matrícula trasera.", "Ligue as luzes de presença e veja a matrícula traseira.", "Allumez les feux de position et regardez la plaque arrière.", "Accendi le luci di posizione e guarda la targa posteriore."),
        R("The expiry date is on the label. If it has a gauge, the needle must be in the green zone.", "Son kullanma tarihi etikette yazar. Göstergesi varsa ibre yeşil bölgede olmalı.", "Das Ablaufdatum steht auf dem Etikett. Hat er ein Manometer, muss die Nadel im grünen Bereich stehen.", "Data ważności jest na etykiecie. Jeśli ma manometr, wskazówka musi być w zielonym polu.", "La fecha de caducidad está en la etiqueta. Si tiene manómetro, la aguja debe estar en la zona verde.", "A data de validade está na etiqueta. Se tiver manómetro, o ponteiro tem de estar na zona verde.", "La date de péremption figure sur l’étiquette. S’il a un manomètre, l’aiguille doit être dans la zone verte.", "La data di scadenza è sull’etichetta. Se ha un manometro, la lancetta deve essere nella zona verde."),
        R("The grooves contain small bars (TWI). If the tread is worn down to them, the tire must be replaced. Check across the whole width; uneven wear points to alignment or suspension issues.", "Oluklarda küçük çubuklar (TWI) vardır. Diş onlara kadar aşındıysa lastik değiştirilmelidir. Tüm genişlik boyunca kontrol et; düzensiz aşınma rot-balans veya süspansiyon sorunlarına işaret eder.", "In den Rillen befinden sich kleine Stege (TWI). Ist das Profil bis dorthin abgefahren, muss der Reifen ersetzt werden. Prüfe über die gesamte Breite; ungleichmäßiger Verschleiß deutet auf Spur- oder Fahrwerksprobleme hin.", "W rowkach znajdują się małe progi (TWI). Jeśli bieżnik zużył się do nich, oponę trzeba wymienić. Sprawdź na całej szerokości; nierówne zużycie wskazuje na problemy ze zbieżnością lub zawieszeniem.", "Los surcos contienen pequeños testigos (TWI). Si el dibujo se ha desgastado hasta ellos, hay que cambiar el neumático. Revisa todo el ancho; un desgaste irregular indica problemas de alineación o suspensión.", "Os sulcos contêm pequenas barras (TWI). Se o piso estiver gasto até elas, o pneu tem de ser substituído. Verifique em toda a largura; desgaste irregular indica problemas de alinhamento ou suspensão.", "Les rainures contiennent de petits témoins (TWI). Si la sculpture est usée jusqu’à eux, le pneu doit être remplacé. Vérifiez sur toute la largeur ; une usure irrégulière indique un problème de géométrie ou de suspension.", "Nelle scanalature ci sono piccoli indicatori (TWI). Se il battistrada è consumato fino a essi, lo pneumatico va sostituito. Controlla su tutta la larghezza; un’usura irregolare indica problemi di convergenza o sospensioni."),
        R("The light comes on for a few seconds with the ignition and must go out. In PRO, module diagnostics reads the airbag fault codes.", "Lamba kontakla birkaç saniye yanar ve sönmelidir. PRO’da modül tanılaması hava yastığı arıza kodlarını okur.", "Die Leuchte geht mit der Zündung für einige Sekunden an und muss erlöschen. In PRO liest die Moduldiagnose die Airbag-Fehlercodes.", "Kontrolka zapala się na kilka sekund po włączeniu zapłonu i musi zgasnąć. W PRO diagnostyka modułów odczytuje kody usterek poduszek powietrznych.", "La luz se enciende unos segundos con el contacto y debe apagarse. En PRO, el diagnóstico de módulos lee los códigos de avería del airbag.", "A luz acende durante alguns segundos com a ignição e tem de apagar. No PRO, o diagnóstico de módulos lê os códigos de avaria do airbag.", "Le voyant s’allume quelques secondes avec le contact et doit s’éteindre. En PRO, le diagnostic des modules lit les codes défaut de l’airbag.", "La spia si accende per qualche secondo con il quadro e deve spegnersi. In PRO la diagnostica dei moduli legge i codici di guasto dell’airbag."),
        R("The lights come on briefly with the ignition and must go out once the engine runs. In PRO, module diagnostics reads the ABS fault codes.", "Lambalar kontakla kısaca yanar ve motor çalışınca sönmelidir. PRO’da modül tanılaması ABS arıza kodlarını okur.", "Die Leuchten gehen mit der Zündung kurz an und müssen erlöschen, sobald der Motor läuft. In PRO liest die Moduldiagnose die ABS-Fehlercodes.", "Kontrolki zapalają się krótko po włączeniu zapłonu i muszą zgasnąć, gdy silnik pracuje. W PRO diagnostyka modułów odczytuje kody usterek ABS.", "Las luces se encienden brevemente con el contacto y deben apagarse cuando el motor funciona. En PRO, el diagnóstico de módulos lee los códigos de avería del ABS.", "As luzes acendem brevemente com a ignição e têm de apagar quando o motor trabalha. No PRO, o diagnóstico de módulos lê os códigos de avaria do ABS.", "Les voyants s’allument brièvement avec le contact et doivent s’éteindre une fois le moteur en marche. En PRO, le diagnostic des modules lit les codes défaut ABS.", "Le spie si accendono brevemente con il quadro e devono spegnersi quando il motore è in moto. In PRO la diagnostica dei moduli legge i codici di guasto ABS."),
        R("The reservoir is under the hood, usually on the driver's side with a yellow cap. The level is visible on its side.", "Depo kaputun altındadır, genellikle sürücü tarafında sarı kapaklıdır. Seviye yan tarafında görünür.", "Der Behälter befindet sich unter der Motorhaube, meist auf der Fahrerseite mit gelber Kappe. Der Stand ist an der Seite sichtbar.", "Zbiorniczek jest pod maską, zwykle po stronie kierowcy z żółtym korkiem. Poziom widać z boku.", "El depósito está bajo el capó, normalmente del lado del conductor con tapón amarillo. El nivel se ve en su lateral.", "O reservatório fica debaixo do capô, normalmente do lado do condutor com tampa amarela. O nível vê-se na lateral.", "Le réservoir est sous le capot, généralement côté conducteur avec un bouchon jaune. Le niveau est visible sur le côté.", "Il serbatoio è sotto il cofano, di solito lato guida con tappo giallo. Il livello si vede sul lato."),
        R("The VIN is usually at the bottom corner of the windshield, on the driver's door sill or on the firewall. Compare all 17 characters with the certificate. The OBD check also reads the VIN stored in the ECU.", "VIN genellikle ön camın alt köşesinde, sürücü kapısı eşiğinde veya tabelada bulunur. 17 karakterin tamamını belgeyle karşılaştır. OBD kontrolü ECU’da saklanan VIN’i de okur.", "Der VIN befindet sich meist an der unteren Ecke der Windschutzscheibe, an der Fahrertürschwelle oder an der Spritzwand. Vergleiche alle 17 Zeichen mit dem Fahrzeugschein. Die OBD-Prüfung liest auch den im Steuergerät gespeicherten VIN.", "VIN jest zwykle w dolnym rogu przedniej szyby, na progu drzwi kierowcy lub na grodzi. Porównaj wszystkie 17 znaków z dokumentem. Sprawdzenie OBD odczytuje też VIN zapisany w ECU.", "El VIN suele estar en la esquina inferior del parabrisas, en el umbral de la puerta del conductor o en el mamparo. Compara los 17 caracteres con el permiso. La comprobación OBD también lee el VIN guardado en la ECU.", "O VIN costuma estar no canto inferior do para-brisas, na soleira da porta do condutor ou no painel corta-fogo. Compare os 17 caracteres com o documento. A verificação OBD também lê o VIN guardado na ECU.", "Le VIN se trouve généralement dans le coin inférieur du pare-brise, sur le seuil de la porte conducteur ou sur la cloison pare-feu. Comparez les 17 caractères avec la carte grise. Le contrôle OBD lit aussi le VIN stocké dans l’ECU.", "Il VIN si trova di solito nell’angolo inferiore del parabrezza, sulla soglia della porta guida o sul paratia. Confronta tutti i 17 caratteri con il libretto. Il controllo OBD legge anche il VIN memorizzato nella ECU."),
        R("The wheel should turn lightly at standstill. With hydraulic steering check the fluid level and leaks; with electric steering (EPS) no steering warning light may be on.", "Direksiyon dururken hafif dönmeli. Hidrolik direksiyonda yağ seviyesini ve sızıntıları kontrol et; elektrikli direksiyonda (EPS) hiçbir direksiyon uyarı lambası yanmamalı.", "Das Lenkrad sollte sich im Stand leicht drehen lassen. Prüfe bei hydraulischer Lenkung Flüssigkeitsstand und Lecks; bei elektrischer Lenkung (EPS) darf keine Lenkungswarnleuchte brennen.", "Kierownica powinna kręcić się lekko na postoju. Przy hydraulicznym wspomaganiu sprawdź poziom płynu i wycieki; przy elektrycznym (EPS) nie może świecić żadna kontrolka układu kierowniczego.", "El volante debe girar con suavidad parado. Con dirección hidráulica revisa el nivel de líquido y las fugas; con dirección eléctrica (EPS) no puede estar encendida ninguna luz de aviso de dirección.", "O volante deve rodar com suavidade parado. Com direção hidráulica verifique o nível do fluido e fugas; com direção elétrica (EPS) não pode estar acesa nenhuma luz de aviso da direção.", "Le volant doit tourner facilement à l’arrêt. Avec une direction hydraulique, vérifiez le niveau de liquide et les fuites ; avec une direction électrique (EPS), aucun voyant de direction ne doit être allumé.", "Il volante deve girare con leggerezza da fermo. Con sterzo idraulico controlla livello del liquido e perdite; con sterzo elettrico (EPS) non deve essere accesa alcuna spia dello sterzo."),
        R("Tire damaged (bulge or cut)", "Lastik hasarlı (şişkinlik veya kesik)", "Reifen beschädigt (Wölbung oder Schnitt)", "Uszkodzona opona (wybrzuszenie lub nacięcie)", "Neumático dañado (bulto o corte)", "Pneu danificado (deformação ou corte)", "Pneu endommagé (hernie ou coupure)", "Pneumatico danneggiato (rigonfiamento o taglio)"),
        R("Tire tread worn out", "Lastik dişi bitmiş", "Reifenprofil abgefahren", "Bieżnik opony starty", "Dibujo del neumático gastado", "Piso do pneu gasto", "Sculpture du pneu usée", "Battistrada dello pneumatico consumato"),
        R("Top up and find out why it dropped (pad wear or a leak).", "Tamamla ve neden düştüğünü bul (balata aşınması veya sızıntı).", "Auffüllen und herausfinden, warum er gesunken ist (Belagverschleiß oder Leck).", "Uzupełnij i dowiedz się, dlaczego spadł (zużycie klocków lub wyciek).", "Rellena y averigua por qué bajó (desgaste de pastillas o fuga).", "Complete e descubra porque desceu (desgaste das pastilhas ou fuga).", "Complétez et trouvez pourquoi il a baissé (usure des plaquettes ou fuite).", "Rabbocca e scopri perché è sceso (usura delle pastiglie o perdita)."),
        R("Try every wiper speed and the washer. The blades must not leave streaks and the reservoir must have fluid.", "Her silecek hızını ve yıkama suyunu dene. Lastikler iz bırakmamalı ve depoda sıvı olmalı.", "Probiere jede Wischerstufe und die Waschanlage. Die Blätter dürfen keine Schlieren hinterlassen, und der Behälter muss Flüssigkeit enthalten.", "Wypróbuj każdą prędkość wycieraczek i spryskiwacz. Pióra nie mogą zostawiać smug, a zbiorniczek musi mieć płyn.", "Prueba cada velocidad de los limpiaparabrisas y el lavaparabrisas. Las escobillas no deben dejar marcas y el depósito debe tener líquido.", "Experimente todas as velocidades dos limpa-para-brisas e o esguicho. As escovas não podem deixar riscos e o reservatório tem de ter líquido.", "Essayez chaque vitesse d’essuie-glace et le lave-glace. Les balais ne doivent pas laisser de traces et le réservoir doit contenir du liquide.", "Prova ogni velocità dei tergicristalli e lo spruzzatore. Le spazzole non devono lasciare aloni e il serbatoio deve contenere liquido."),
        R("Turn signal not working", "Sinyal çalışmıyor", "Blinker funktioniert nicht", "Kierunkowskaz nie działa", "El intermitente no funciona", "O pisca não funciona", "Le clignotant ne fonctionne pas", "L’indicatore di direzione non funziona"),
        R("Turn the wheel fully both ways while stationary and listen. Knocks felt in the wheel over bumps point to worn rods or ends.", "Dururken direksiyonu iki yöne de sonuna kadar çevir ve dinle. Tümseklerde direksiyonda hissedilen vuruntular aşınmış rotlara veya rot başlarına işaret eder.", "Drehe das Lenkrad im Stand voll nach beiden Seiten und höre hin. Im Lenkrad spürbares Klopfen über Unebenheiten deutet auf verschlissene Stangen oder Köpfe hin.", "Na postoju obróć kierownicę do oporu w obie strony i nasłuchuj. Stuki wyczuwalne w kierownicy na nierównościach wskazują na zużyte drążki lub końcówki.", "Gira el volante a tope a ambos lados con el coche parado y escucha. Golpes que se notan en el volante sobre baches indican barras o rótulas desgastadas.", "Rode o volante totalmente para os dois lados parado e escute. Pancadas sentidas no volante em lombas indicam barras ou rótulas gastas.", "Tournez complètement le volant dans les deux sens à l’arrêt et écoutez. Des cognements ressentis dans le volant sur les bosses indiquent des biellettes ou rotules usées.", "Gira il volante a fondo nei due sensi da fermo e ascolta. Colpi avvertiti nel volante sulle buche indicano barre o terminali usurati."),
        R("VIN unreadable or does not match the certificate", "VIN okunamıyor veya belgeyle eşleşmiyor", "VIN unlesbar oder stimmt nicht mit dem Fahrzeugschein überein", "VIN nieczytelny lub niezgodny z dowodem", "VIN ilegible o no coincide con el permiso", "VIN ilegível ou não coincide com o documento", "VIN illisible ou non conforme à la carte grise", "VIN illeggibile o non corrispondente al libretto"),
        R("Visibility", "Görüş", "Sicht", "Widoczność", "Visibilidad", "Visibilidade", "Visibilité", "Visibilità"),
        R("Warning triangle missing", "Reflektör eksik", "Warndreieck fehlt", "Brak trójkąta ostrzegawczego", "Falta el triángulo de emergencia", "Falta o triângulo de sinalização", "Triangle de signalisation manquant", "Triangolo di emergenza mancante"),
        R("When braking hard, does the car stay straight without the steering wheel shaking?", "Sert fren yaparken araç düz gidiyor ve direksiyon titremiyor mu?", "Bleibt das Fahrzeug beim kräftigen Bremsen geradeaus, ohne dass das Lenkrad zittert?", "Czy przy mocnym hamowaniu auto jedzie prosto, a kierownica nie drży?", "Al frenar fuerte, ¿el coche va recto sin que tiemble el volante?", "Ao travar a fundo, o carro segue em linha reta sem o volante tremer?", "En freinant fort, la voiture reste-t-elle droite sans que le volant tremble ?", "Frenando forte, l’auto resta dritta senza che il volante vibri?"),
        R("Windows tinted beyond the limit", "Camlar sınırın ötesinde filmli", "Scheiben über den Grenzwert hinaus getönt", "Szyby przyciemnione ponad limit", "Ventanillas tintadas por encima del límite", "Vidros com película acima do limite", "Vitres teintées au-delà de la limite", "Vetri oscurati oltre il limite"),
        R("Windshield crack on the driver's side", "Ön camda sürücü tarafında çatlak", "Riss in der Windschutzscheibe auf der Fahrerseite", "Pęknięcie przedniej szyby po stronie kierowcy", "Grieta en el parabrisas del lado del conductor", "Fissura no para-brisas do lado do condutor", "Fissure du pare-brise côté conducteur", "Crepa nel parabrezza lato guida"),
        R("Wipers or washer not working", "Silecekler veya yıkama suyu çalışmıyor", "Wischer oder Waschanlage funktionieren nicht", "Wycieraczki lub spryskiwacz nie działają", "Los limpiaparabrisas o el lavaparabrisas no funcionan", "Os limpa-para-brisas ou o esguicho não funcionam", "Les essuie-glaces ou le lave-glace ne fonctionnent pas", "Tergicristalli o spruzzatore non funzionano"),
        R("With a warm engine, have someone rev it hard while you watch the tailpipe. Black means a rich mixture or diesel soot, blue means burning oil, thick white means burning coolant.", "Motor sıcakken birine sert gaz verdir ve egzoz borusunu izle. Siyah zengin karışım veya dizel isi, mavi yanan yağ, yoğun beyaz yanan soğutma suyu demektir.", "Lasse bei warmem Motor jemanden kräftig Gas geben, während du das Endrohr beobachtest. Schwarz bedeutet fettes Gemisch oder Dieselruß, blau verbrennendes Öl, dichtes Weiß verbrennendes Kühlmittel.", "Przy rozgrzanym silniku poproś kogoś o mocne gazowanie, a ty obserwuj końcówkę wydechu. Czarny oznacza bogatą mieszankę lub sadzę diesla, niebieski palący się olej, gęsty biały palący się płyn chłodzący.", "Con el motor caliente, haz que alguien acelere a fondo mientras miras el tubo de escape. Negro indica mezcla rica u hollín de diésel, azul aceite quemándose, blanco espeso refrigerante quemándose.", "Com o motor quente, peça a alguém que acelere a fundo enquanto vê o tubo de escape. Preto indica mistura rica ou fuligem de diesel, azul óleo a queimar, branco denso líquido de arrefecimento a queimar.", "Moteur chaud, faites accélérer fort quelqu’un pendant que vous observez le pot d’échappement. Noir = mélange riche ou suie de diesel, bleu = huile qui brûle, blanc épais = liquide de refroidissement qui brûle.", "A motore caldo, fai accelerare forte qualcuno mentre guardi il tubo di scarico. Nero indica miscela ricca o fuliggine diesel, blu olio che brucia, bianco denso liquido di raffreddamento che brucia."),
        R("With the engine running, press the pedal with moderate force and hold it for 10 s. A soft or sinking pedal means air or a leak in the system.", "Motor çalışırken pedala orta kuvvetle bas ve 10 sn tut. Yumuşak veya çöken pedal sistemde hava veya sızıntı demektir.", "Drücke bei laufendem Motor das Pedal mit mäßiger Kraft und halte es 10 s. Ein weiches oder durchsinkendes Pedal bedeutet Luft oder ein Leck im System.", "Przy pracującym silniku naciśnij pedał z umiarkowaną siłą i przytrzymaj 10 s. Miękki lub opadający pedał oznacza powietrze lub wyciek w układzie.", "Con el motor en marcha, pisa el pedal con fuerza moderada y mantenlo 10 s. Un pedal blando o que se hunde indica aire o una fuga en el sistema.", "Com o motor a trabalhar, pise o pedal com força moderada e mantenha-o 10 s. Um pedal mole ou que afunda indica ar ou uma fuga no sistema.", "Moteur en marche, appuyez sur la pédale avec une force modérée et maintenez 10 s. Une pédale molle ou qui s’enfonce indique de l’air ou une fuite dans le circuit.", "A motore acceso, premi il pedale con forza moderata e mantienilo 10 s. Un pedale molle o che affonda indica aria o una perdita nell’impianto."),
